FROZEN_SOURCES = {'semantic_state_cli.py': '', 'semantic_state_pipeline.py': '', 'semantic_state_renderer.cjs': '', 'semantic_state_capture.cjs': '', 'relation_motion_maintenance_render.py': '', 'relation_browser_watchdog.py': '', 'relation_browser_shim.py': '', 'runtime_contracts.py': '', 'semantic_validator.py': ''}
BROWSER_SUPPORT = '\nimport argparse\nimport base64\nimport fcntl\nimport json\nimport os\nfrom pathlib import Path\nimport re\nimport selectors\nimport shutil\nimport stat\nimport subprocess\nimport sys\nimport tempfile\nimport time\n\nREADY_TIMEOUT = 5\nSTOP_TIMEOUT = 8\n\ndef descriptor(value):\n    if not re.fullmatch(r"/dev/fd/[0-9]+", value):\n        raise ValueError("expected an inherited /dev/fd descriptor")\n    number = int(value.rsplit("/", 1)[1])\n    if number < 3 or not stat.S_ISREG(os.fstat(number).st_mode):\n        raise ValueError("descriptor must refer to a regular file")\n    return number\n\ndef publish(candidate, target):\n    if os.fstat(target).st_size != 0:\n        raise ValueError("output descriptor changed during render")\n    try:\n        with candidate.open("rb") as rendered, os.fdopen(os.dup(target), "wb") as destination:\n            destination.seek(0)\n            shutil.copyfileobj(rendered, destination, length=1024 * 1024)\n            destination.flush()\n            os.fsync(destination.fileno())\n    except BaseException:\n        # Catchable failures roll back our staging bytes. SIGKILL still requires\n        # the outer executor\'s transaction rollback; this is not atomic publish.\n        os.ftruncate(target, 0)\n        os.lseek(target, 0, os.SEEK_SET)\n        raise\n\ndef rollback(target):\n    if target is None:\n        return\n    os.ftruncate(target, 0)\n    os.lseek(target, 0, os.SEEK_SET)\n\ndef read_ready(process):\n    selector = selectors.DefaultSelector()\n    payload = bytearray()\n    deadline = time.monotonic() + READY_TIMEOUT\n    try:\n        selector.register(process.stdout, selectors.EVENT_READ)\n        while b"\\n" not in payload:\n            remaining = deadline - time.monotonic()\n            if remaining <= 0:\n                raise TimeoutError("browser watchdog ready timed out")\n            if not selector.select(remaining):\n                raise TimeoutError("browser watchdog ready timed out")\n            block = os.read(process.stdout.fileno(), 4096 - len(payload))\n            if not block:\n                raise ValueError("browser watchdog exited before ready")\n            payload.extend(block)\n            if len(payload) >= 4096:\n                raise ValueError("browser watchdog ready response too large")\n        line, trailing = bytes(payload).split(b"\\n", 1)\n        if trailing:\n            raise ValueError("browser watchdog emitted unexpected stdout")\n        ready = json.loads(line)\n        if (type(ready) is not dict or set(ready) != {"root", "socket", "token"}\n                or any(type(ready[key]) is not str or not ready[key]\n                       for key in ("root", "socket", "token"))):\n            raise ValueError("browser watchdog ready response is invalid")\n        root = Path(ready["root"]).resolve(strict=True)\n        if not root.is_dir() or not Path(ready["socket"]).is_socket():\n            raise ValueError("browser watchdog resources are invalid")\n        ready["root"] = str(root)\n        return ready\n    finally:\n        selector.close()\n\ndef start_watchdog(parent):\n    read_fd, write_fd = os.pipe()\n    os.set_inheritable(write_fd, False)\n    source = base64.b64decode(FROZEN_SOURCES["relation_browser_watchdog.py"], validate=True)\n    process = None\n    try:\n        process = subprocess.Popen(\n            [sys.executable, "-", "--heartbeat-fd", str(read_fd),\n             "--parent", str(parent)],\n            stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE,\n            pass_fds=(read_fd,), start_new_session=True,\n        )\n        os.close(read_fd)\n        read_fd = -1\n        process.stdin.write(source)\n        process.stdin.close()\n        process.stdin = None\n        return process, write_fd, read_ready(process)\n    except BaseException:\n        if read_fd >= 0:\n            os.close(read_fd)\n        os.close(write_fd)\n        if process is not None:\n            try:\n                process.communicate(timeout=2)\n            except subprocess.TimeoutExpired:\n                process.kill()\n                process.communicate(timeout=2)\n            except OSError:\n                process.kill()\n        raise\n\ndef stop_watchdog(process, heartbeat):\n    close_error = None\n    try:\n        os.close(heartbeat)\n    except OSError as error:\n        close_error = error\n    try:\n        stdout, stderr = process.communicate(timeout=STOP_TIMEOUT)\n    except subprocess.TimeoutExpired as error:\n        process.kill()\n        process.communicate(timeout=2)\n        raise RuntimeError("browser watchdog cleanup timed out") from error\n    if close_error is not None or process.returncode or stdout:\n        detail = stderr.decode("utf-8", errors="replace")[-2000:]\n        raise RuntimeError("browser watchdog cleanup failed: " + detail) from close_error\n\ndef main():\n    parser = argparse.ArgumentParser(description="Frozen relation renderer")\n    for name in ("brief", "output", "node", "playwright", "browser", "ffmpeg", "ffprobe"):\n        parser.add_argument("--" + name, required=True)\n    args = parser.parse_args()\n    target = None\n    rollback_target = None\n    watchdog = None\n    heartbeat = -1\n    try:\n        source, target = descriptor(args.brief), descriptor(args.output)\n        source_stat, target_stat = os.fstat(source), os.fstat(target)\n        if ((source_stat.st_dev, source_stat.st_ino) == (target_stat.st_dev, target_stat.st_ino)\n                or target_stat.st_size != 0 or source_stat.st_size > 4 * 1024 * 1024\n                or fcntl.fcntl(target, fcntl.F_GETFL) & os.O_ACCMODE == os.O_RDONLY):\n            raise ValueError("invalid input/output descriptors")\n        rollback_target = target\n        parent = Path(tempfile.gettempdir()).resolve(strict=True)\n        watchdog, heartbeat, ready = start_watchdog(parent)\n        root = Path(ready["root"])\n        tools = root / "edit" / "hd" / "tools"\n        tools.mkdir(parents=True)\n        for name, encoded in FROZEN_SOURCES.items():\n            data = base64.b64decode(encoded, validate=True)\n            path = tools / name\n            if name == "relation_browser_shim.py":\n                _, body = data.split(b"\\n", 1)\n                data = b"#!" + os.fsencode(sys.executable) + b"\\n" + body\n            path.write_bytes(data)\n        shim = tools / "relation_browser_shim.py"\n        shim.chmod(0o700)\n        brief = root / "brief.json"\n        brief.write_bytes(os.pread(source, source_stat.st_size, 0))\n        output = root / "candidate.mp4"\n        command = [sys.executable, str(tools / "relation_motion_cli.py"),\n                   "--brief", str(brief), "--output", str(output)]\n        for name in ("node", "playwright", "ffmpeg", "ffprobe"):\n            command.extend(["--" + name, getattr(args, name)])\n        command.extend(["--browser", str(shim)])\n        environment = dict(\n            os.environ,\n            HD_BROWSER_SOCKET=ready["socket"],\n            HD_BROWSER_TOKEN=ready["token"],\n            HD_BROWSER_REAL=args.browser,\n            HD_RELATION_PARENT_GROUP=str(os.getpgrp()),\n        )\n        result = subprocess.run(command, check=False, env=environment)\n        if result.returncode:\n            raise ValueError("relation renderer failed")\n        publish(output, target)\n        active, active_heartbeat = watchdog, heartbeat\n        watchdog, heartbeat = None, -1\n        stop_watchdog(active, active_heartbeat)\n        return 0\n    except (OSError, RuntimeError, TimeoutError, ValueError) as error:\n        cleanup_error = None\n        if watchdog is not None:\n            try:\n                stop_watchdog(watchdog, heartbeat)\n            except (OSError, RuntimeError) as failure:\n                cleanup_error = failure\n        try:\n            rollback(rollback_target)\n        except OSError as failure:\n            cleanup_error = cleanup_error or failure\n        if cleanup_error is not None:\n            error = RuntimeError(str(error) + "; " + str(cleanup_error))\n        print("frozen relation render failed: " + str(error), file=sys.stderr)\n        return 1\n\nif __name__ == "__main__":\n    raise SystemExit(main())\n'
SEMANTIC_ENTRY = '\nimport argparse\nimport fcntl\nimport os\nfrom pathlib import Path\nimport subprocess\nimport sys\nimport tempfile\nimport base64\nimport json\n\ndef parse_runtime_contracts(raw):\n    if len(raw.encode("utf-8")) > 65536:\n        raise ValueError("runtime contracts too large")\n    def unique(pairs):\n        value = {}\n        for key, item in pairs:\n            if key in value:\n                raise ValueError("duplicate runtime contract key")\n            value[key] = item\n        return value\n    return json.loads(raw, object_pairs_hook=unique)\n\ndef semantic_main():\n    parser = argparse.ArgumentParser(description="Frozen semantic-state renderer")\n    for key in ("brief", "output", "node", "playwright", "browser", "ffmpeg", "ffprobe"):\n        parser.add_argument("--" + key, required=True)\n    parser.add_argument("--runtime-contracts", required=True)\n    args = parser.parse_args()\n    support = {"__name__": "frozen_browser_support", "FROZEN_SOURCES": FROZEN_SOURCES}\n    exec(compile(BROWSER_SUPPORT, "frozen_browser_support.py", "exec"), support)\n    target = None\n    watchdog = None\n    heartbeat = -1\n    try:\n        source = support["descriptor"](args.brief)\n        output = support["descriptor"](args.output)\n        original, destination = os.fstat(source), os.fstat(output)\n        if (os.path.samestat(original, destination) or destination.st_size != 0\n                or original.st_size > 4 * 1024 * 1024\n                or fcntl.fcntl(output, fcntl.F_GETFL) & os.O_ACCMODE == os.O_RDONLY):\n            raise ValueError("invalid input/output descriptors")\n        target = output\n        runtime = {"__name__": "frozen_runtime_contracts"}\n        exec(compile(base64.b64decode(FROZEN_SOURCES["runtime_contracts.py"], validate=True), "runtime_contracts.py", "exec"), runtime)\n        contracts = runtime["normalize_contracts"](parse_runtime_contracts(args.runtime_contracts))\n        for key, contract in contracts.items():\n            if getattr(args, key) != contract["path"]:\n                raise ValueError("runtime argument differs from contract: " + key)\n            if key in ("node", "ffmpeg", "ffprobe") and contract.get("library_discovery") != "mach_o_static_v1":\n                raise ValueError("runtime requires static library discovery: " + key)\n        runtime["verify_contracts"](contracts)\n        watchdog, heartbeat, ready = support["start_watchdog"](Path(tempfile.gettempdir()).resolve(strict=True))\n        root = Path(ready["root"])\n        tools = root / "edit" / "hd" / "tools"\n        tools.mkdir(parents=True)\n        # Close namespace-package fallback into another Agent\'s project tree.\n        for package in (root / "edit", root / "edit" / "hd", tools):\n            (package / "__init__.py").write_bytes(b"")\n        for name, encoded in FROZEN_SOURCES.items():\n            data = base64.b64decode(encoded, validate=True)\n            if name == "relation_browser_shim.py":\n                data = b"#!" + os.fsencode(sys.executable) + b"\\n" + data.split(b"\\n", 1)[1]\n            (tools / name).write_bytes(data)\n        shim = tools / "relation_browser_shim.py"\n        shim.chmod(0o700)\n        validator = {"__name__": "frozen_snapshot"}\n        exec(compile(base64.b64decode(FROZEN_SOURCES["semantic_validator.py"], validate=True), "semantic_validator.py", "exec"), validator)\n        executables = {}\n        for key in ("node", "ffmpeg", "ffprobe"):\n            snapshot = root / key\n            validator["_snapshot"](Path(contracts[key]["path"]), snapshot, contracts[key]["sha256"])\n            executables[key] = str(snapshot)\n        brief = root / "brief.json"\n        brief.write_bytes(os.pread(source, original.st_size, 0))\n        candidate = root / "candidate.mp4"\n        command = [sys.executable, str(tools / "semantic_state_cli.py"),\n            "--brief", str(brief), "--output", str(candidate), "--browser", str(shim)]\n        for key in ("node", "playwright", "ffmpeg", "ffprobe"):\n            command.extend(["--" + key, executables.get(key, getattr(args, key))])\n        environment = dict(os.environ, HD_BROWSER_SOCKET=ready["socket"],\n            HD_BROWSER_TOKEN=ready["token"], HD_BROWSER_REAL=args.browser,\n            HD_RELATION_PARENT_GROUP=str(os.getpgrp()))\n        if subprocess.run(command, env=environment, check=False).returncode:\n            raise ValueError("semantic renderer failed")\n        runtime["verify_contracts"](contracts)\n        support["publish"](candidate, target)\n        active, active_heartbeat = watchdog, heartbeat\n        watchdog, heartbeat = None, -1\n        support["stop_watchdog"](active, active_heartbeat)\n        return 0\n    except (OSError, RuntimeError, ValueError) as error:\n        if watchdog is not None:\n            try:\n                support["stop_watchdog"](watchdog, heartbeat)\n            except (OSError, RuntimeError) as cleanup:\n                error = RuntimeError(str(error) + "; " + str(cleanup))\n        try:\n            support["rollback"](target)\n        except OSError as cleanup:\n            error = RuntimeError(str(error) + "; " + str(cleanup))\n        print("frozen semantic render failed: " + str(error), file=sys.stderr)\n        return 1\n\nif __name__ == "__main__":\n    raise SystemExit(semantic_main())\n'
exec(compile(SEMANTIC_ENTRY, 'semantic_entry.py', 'exec'))
